import {detailView,aboutView,contactView,socialView} from './detail-views.js';
/** Prototype controller. All AI and admin outcomes are simulated and kept in memory. No credentials are persisted or transmitted. */
import {createNavigation,routeLabel} from './navigation.mjs';
import {DIG_DURATION} from './motion.mjs';
import {createWorld} from './scene.js';
import {actionKeys,shortcutAction} from './shortcuts.mjs';
const $=s=>document.querySelector(s),surface=$('#surface'),modal=$('#modal');
const state={carryFrom:'start',strikes:0,digs:0,sessions:[],stage:'start',smashed:false,busy:false,configured:false,provider:'OpenAI',model:'示例模型',page:'scene',reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,messages:[],request:null,question:'',proposal:null,version:1,published:'让探索成为个人网站的一部分。',records:[],scope:'全站公开内容',returnPage:'home'};
const projects=[{id:'mars',name:'远行手记',kind:'交互网站 / 设计示例',num:'01',art:'MARS',desc:'把一次短暂的探索，变成认识一个人的入口。',body:'这是一份个人站设计示例：访客可以在火星上打造工具、发现宝箱，也可以直接阅读内容。探索完成后，模型配置化作一张船票。',sections:[['想解决的问题','如何让个人网站有记忆点，同时让只想看作品的人不用学习游戏规则。'],['交互取舍','两条入口共享同一个内容站。场景服务于探索；项目与文章采用稳定的阅读布局；问答随时可以收起。'],['状态与边界','当前为可操作原型。模型验证、AI 回答与管理发布均为模拟；尚无真实业务后端。']]},{id:'index',name:'线索索引',kind:'知识阅读工具 / 概念示例',num:'02',art:'INDEX',desc:'从一个问题，找到值得读的原文。',body:'这是用于演示项目详情与引用联动的虚构概念项目，不是站长已完成的真实经历或成果。',sections:[['概念','将零散笔记整理为可追溯的主题索引，让问题与出处相连。'],['设计范围','阅读、主题查找和来源跳转；本原型只演示公开示例内容，不连接个人知识库。'],['尚待验证','真实检索质量、资料维护成本和模型评估需要在实现阶段验证。']]}];
const articles=[{id:'explore',title:'让探索有意义，而不挡住阅读',date:'设计手记 · 01',summary:'每一个可玩的动作，都应该给访客一个继续的理由。',parts:[['探索的回报','火星上，铲子通向宝箱，宝箱通向船票。动作会改变接下来的体验，而不只是播放一个动画。'],['保留另一条路','有些人愿意探索，有些人只想看项目。砸炉与直接浏览保留同一个目的地，让两种访客都能按自己的节奏前进。'],['把舞台留给内容','进入文章后，镜头停止追逐指针。正文、章节和来源承担主要工作；场景在需要时再回来。']]},{id:'sources',title:'一个回答，也应该有来路',date:'设计手记 · 02',summary:'答案的价值，不只在于说得像，还在于能找到依据。',parts:[['从公开材料开始','问答只使用获准公开的博客、项目和个人介绍。没有资料支持的问题，应明确说明不知道。'],['引用是一条返回路径','回答中的引用应直接定位到对应文章或项目的具体段落，并高亮依据。访客看完后可以回到对话，保留问题与上下文。'],['配置由访客选择','访客选择厂商、模型并提供自己的 API Key。费用与处理方式需清楚说明，普通阅读不依赖配置。']]},{id:'boundaries',title:'给 Agent 一条清楚的边界',date:'设计手记 · 03',summary:'先给出具体变更，再决定是否执行。',parts:[['从提案开始','站长 Agent 先展示目标、依据、修改前后内容与影响页面。发送消息不等于授权发布。'],['确认对应一个版本','如果目标内容变化，旧提案需要重新检查。取消不会写入，重复确认不应重复执行。'],['把结果说清楚','保存、发布和问答来源更新是不同的步骤。某一步失败时，说明真实状态，再提供恢复路径。']]}];
let navigation,world,storyTimer,flightTimer,configTimer,toastTimer;
try{world=createWorld($('#world'))}catch(error){console.error(error);$('#scene').insertAdjacentHTML('beforeend','<div class="error-screen">3D 场景暂时无法加载。请直接浏览主站。</div>')}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function stopPending(){clearTimeout(storyTimer);clearTimeout(flightTimer);state.busy=false}
function showPage(page){if(modal.open)modal.close();state.page=page;document.body.dataset.page=page;surface.hidden=page==='scene';$('#game').hidden=page!=='scene';$('#flight').hidden=true;world?.setActive(page==='scene');document.body.classList.toggle('reading',page!=='scene');window.scrollTo(0,0)}
function readView(){return{scroll:window.scrollY,chatScroll:$('.conversation-scroll')?.scrollTop||0,filters:Object.fromEntries(['search','project-search','admin-input','admin-kind'].filter(id=>$('#'+id)).map(id=>[id,$('#'+id).value]))}}
function restoreView(view){if(!view)return;requestAnimationFrame(()=>{for(const [id,value] of Object.entries(view.filters||{})){const input=$('#'+id);if(input){input.value=value;input.dispatchEvent(new Event('input'))}}window.scrollTo(0,view.scroll||0);const chatScroll=$('.conversation-scroll');if(chatScroll)chatScroll.scrollTop=view.chatScroll||0})}
function navigate(route){navigation.go(route)}
function backButton(fallback='home',style='back'){return `<button class="${style}" data-action="back" data-fallback="${fallback}">← 返回${routeLabel(navigation.previous()||fallback)}</button>`}
function chrome(tab){return `<div class="subnav">${[['home','概览'],['projects','项目'],['articles','文章'],['about','关于'],['contact','联系']].map(([id,label])=>`<button class="chip ${tab===id?'active':''}" data-route="${id}">${label}</button>`).join('')}</div>`}
function footer(){return '<footer class="footer"><span>远行手记 / FIELDNOTES · 作品与 AI 为设计演示</span><div><button data-action="scene">重返火星</button> · <button data-route="admin">站长工作台 · 演示</button></div></footer>'}
function projectCard(p){return `<button class="project" data-route="project/${p.id}"><div class="project-art ${p.id==='index'?'space':'mars-art'}"><span>${p.art}</span><i class="orbit"></i><small>0${p.num} / CONCEPT</small></div><div class="project-info"><div><h3>${p.name}</h3><p>${p.kind}</p></div><span>↗</span></div></button>`}
function articleRows(list){return list.length?list.map((a,i)=>`<button class="article-row" data-route="article/${a.id}"><span>0${i+1}</span><h3>${a.title}</h3><span class="date">${a.date}</span><span>↗</span></button>`).join(''):'<p class="empty">没有匹配内容。换个关键词试试，或查看全部文章。</p>'}
function home(tab='home'){
 showPage(tab);
 if(tab==='home'){
 surface.innerHTML=`<div class="desk-intro"><span class="eyebrow">FIELDNOTES — BACK ON EARTH</span><h1><a class="name-link" href="#/social" data-route="social" aria-label="黄凌波 · 查看社媒主页">黄凌波<span aria-hidden="true">↗</span></a></h1><p>带回一些，新发现。<span class="intro-divider"> / </span>作品、文字和未完成的念头。</p></div><div class="desk" aria-label="归航桌面"><button class="desk-object postcard" data-route="project/mars"><img src="mars-panorama.png" alt="火星岩石与远山"><span class="postmark">MARS<br>RETURN MAIL</span><span class="postcard-caption"><strong>远行手记</strong><span>一个可以走进去的个人网站 ↗</span></span></button><button class="desk-object notebook" data-route="articles"><span class="notebook-label">随手记 / NOTES</span><strong>把好奇，<br>留在纸上。</strong><span class="notebook-bottom">三篇设计手记 <span>打开阅读 ↗</span></span></button><button class="desk-object index-card" data-route="project/index"><span class="eyebrow">EXPERIMENT / 概念示例</span><strong>线索索引</strong><span class="index-type">A thought.<br>A source.<br>A connection.</span><span>让每个答案有来处 ↗</span></button><button class="desk-object personal-note" data-route="about"><span class="eyebrow">A NOTE ABOUT ME</span><strong>你好，<br>欢迎来坐坐。</strong><span>这张纸，留给真实的自我介绍。</span><span class="note-link">关于我 ↗</span></button><button class="desk-object boarding-stub" data-action="ai"><span>EARTH / OPEN CHANNEL</span><strong>带着问题来。</strong><span>与本站 AI 对话 ↗</span></button></div><div class="desk-bottom"><span>点击一件物品，打开一段内容。<br><small>当前作品与文字为原型设计示例。</small></span><button data-action="scene">↖ 前往火星</button></div><nav class="dock" aria-label="主站导航">${[['home','桌面'],['projects','作品'],['articles','手记'],['about','关于'],['contact','联系']].map(([id,label])=>`<button data-route="${id}" class="${id==='home'?'active':''}">${label}</button>`).join('')}<span></span><button data-action="ai">对话 ↗</button></nav>${footer()}`;
 }else{
 surface.innerHTML=`${backButton()}<div class="archive-title"><span class="eyebrow">FIELDNOTES / ${tab==='projects'?'WORK':'WRITING'}</span><h1>${tab==='projects'?'作品档案':'桌上的手记'}<small>${tab==='projects'?'2 个设计示例':'3 篇设计手记'}</small></h1></div>${chrome(tab)}${tab==='projects'?`<input class="search" id="project-search" placeholder="查找项目名称或简介" aria-label="查找项目"><div class="project-grid" id="project-list">${projects.map(projectCard).join('')}</div>`:`<input class="search" id="search" placeholder="查找文章标题或关键词" aria-label="查找文章"><div id="article-list">${articleRows(articles)}</div>`}${footer()}`;
 $('#project-search')?.addEventListener('input',e=>{const found=projects.filter(p=>(p.name+p.desc+p.body).includes(e.target.value.trim()));$('#project-list').innerHTML=found.length?found.map(projectCard).join(''):'<p>没有匹配项目。试试其他关键词。</p>'});
 $('#search')?.addEventListener('input',e=>{$('#article-list').innerHTML=articleRows(articles.filter(a=>(a.title+a.summary+a.parts.flat().join('')).includes(e.target.value.trim())))})
 }
}
function detail(type,id,anchor){const item=(type==='project'?projects:articles).find(x=>x.id===id);if(!item){showPage('not-found');surface.innerHTML='<h1>这条线索暂时不存在。</h1><button class="primary" data-route="home">前往主站</button>';return}showPage(type);surface.innerHTML=detailView(type,item,{back:backButton(type==='project'?'projects':'articles'),update:type==='project'&&id==='mars'&&state.version>1?`<div class="callout">工作台更新 · 模拟 v${state.version}<p>${esc(state.published)}</p></div>`:''})+footer()+(anchor&&navigation.previous()==='chat'?backButton('chat','citation-return'):'');if(anchor){requestAnimationFrame(()=>{const section=document.getElementById(anchor);section?.classList.add('cited');section?.scrollIntoView({block:'center',behavior:'instant'});section?.setAttribute('tabindex','-1');section?.focus({preventScroll:true})})}}
function about(){showPage('about');surface.innerHTML=aboutView(backButton())+footer()}
function contact(){showPage('contact');surface.innerHTML=contactView(backButton())+footer()}
function mission(){
 const defs={start:['熔炉','先打开炉门。','铁料 × 1',[['open-furnace','打开炉门'],['carry','搬起熔炉']]],forge:['锻造工具',`锻打 ${state.strikes} / 3 · 再敲实一点。`,'铁料 × 1',[['hammer','锻打一锤'],['carry','搬起熔炉']]],tool:['工具完成','拿起你的铲子。','铲子已锻好',[['take-shovel','拿起铲子']]],shovel:['越过山坡',`铲土 ${state.digs} / 5 · 继续挖，看看下面有什么。`,'铲子 × 1',[['dig','铲一下'],['walk-dig','走向坡后（辅助）']]],uncovered:['露出宝箱','清理完毕，打开箱盖。','铲子 × 1',[['open-chest','打开宝箱']]],chest:['发现船票','箱子里藏着一段新旅程。','未签发的船票',[['configure','配置模型，签发船票']]],ticket:['准备出发','走到飞船旁，打开舱门。','星际船票 × 1',[['open-hatch','打开舱门'],['walk-ship','走向飞船（辅助）']]],hatch:['舱门已开启','沿着舷梯，登上飞船。','星际船票 × 1',[['board','登上飞船']]],boarded:['准备发射','目的地：地球。','已登船',[['launch','点火，前往地球']]],carrying:['另一条路','负重缓行 · R 放下 · X 砸下','熔炉 × 1',[['put-down','放下熔炉'],['smash','砸下熔炉']]]};
 const d=defs[state.stage]||defs.start;$('#step').textContent=d[0];$('#mission').textContent=d[1];$('#inventory').textContent=d[2];$('#hint').textContent='WASD / 方向键移动 · 按按钮上的快捷键 · 每按一次做一个动作';$('.actions').innerHTML=d[3].map(([id,label],i)=>`<button class="${i?'subtle':'primary'}" data-action="${id}" ${actionKeys[id]?`aria-keyshortcuts="${actionKeys[id]}"`:""} ${state.busy?'disabled':''}>${label}${actionKeys[id]?` <kbd>${actionKeys[id]}</kbd>`:""}</button>`).join('');
}
function storyAction(action){
 const near=id=>!world||world.near(id);const requireNear=id=>{if(near(id))return true;toast(`先走近${id==='furnace'?'熔炉':id==='dig'?'山坡后的挖掘点':'飞船'}。点击地面或使用方向键移动。`);return false};
 const animate=(kind,next,ms=1000)=>{state.busy=true;world?.action(kind);mission();storyTimer=setTimeout(()=>{world?.finish(kind==='forge'?'hammer':kind);next();state.busy=false;mission()},state.reduced?350:ms)};
 const actions=['open-furnace','hammer','take-shovel','dig','open-chest','carry','put-down','smash','walk-dig','walk-ship','open-hatch','board','ticket-scene'];
 if(!actions.includes(action))return false;if(state.busy)return true;
 if(action==='walk-dig'){world?.go('dig');return true}if(action==='walk-ship'){world?.go('ship');return true}
 if(action==='ticket-scene'){closeDialog();if(state.traveled||state.smashed){world?.reset();state.traveled=state.smashed=false;state.strikes=state.digs=0}state.stage='ticket';navigate('scene');mission();return true}
 if(action==='open-furnace'&&state.stage==='start'&&requireNear('furnace'))animate('open-furnace',()=>state.stage='forge');
 if(action==='hammer'&&state.stage==='forge'&&requireNear('furnace'))animate('forge',()=>{state.strikes++;if(state.strikes===3)state.stage='tool'},850);
 if(action==='take-shovel'&&state.stage==='tool'&&requireNear('furnace')){world?.finish('forge');state.stage='shovel';mission();toast('沿着山坡向前走。翻过坡顶，后面有挖掘标记。')}
 if(action==='dig'&&state.stage==='shovel'&&requireNear('dig'))animate('dig',()=>{state.digs++;if(state.digs===5)state.stage='uncovered'},DIG_DURATION*1000);
 if(action==='open-chest'&&state.stage==='uncovered'&&requireNear('dig'))animate('open-chest',()=>{state.stage='chest';config()},900);
 if(action==='carry'&&['start','forge'].includes(state.stage)&&requireNear('furnace')){state.carryFrom=state.stage;state.stage='carrying';animate('carry',()=>{},900)}
 if(action==='put-down'&&state.stage==='carrying'&&!world.canDrop()){toast('前面空间不够，转身或走到空地再放下。');return true}if(action==='put-down'&&state.stage==='carrying')animate('put-down',()=>{state.stage=state.carryFrom;toast('熔炉已稳稳放下，锻造进度保留。')},900);
 if(action==='smash'&&state.stage==='carrying')animate('smash',()=>{state.smashed=true;navigate('home')},1000);
 if(action==='open-hatch'&&state.stage==='ticket'&&requireNear('ship'))animate('open-hatch',()=>state.stage='hatch',1100);
 if(action==='board'&&state.stage==='hatch'&&requireNear('ship'))animate('board',()=>state.stage='boarded',1000);
 return true;
}
function scene(){stopPending();if(state.smashed||state.traveled){state.traveled=false;world?.reset();state.stage='start';state.strikes=0;state.digs=0;state.smashed=false}showPage('scene');world?.finish('idle');mission()}
function openDialog(html){$('#dialog-content').innerHTML=html;if(!modal.open)modal.showModal();world?.setActive(false)}
function closeDialog(){clearTimeout(configTimer);modal.close();world?.setActive(state.page==='scene')}
modal.addEventListener('close',()=>{clearTimeout(configTimer);world?.setActive(state.page==='scene')});
function config(){state.returnPage=state.page;openDialog(`<div class="modal-top"><span class="eyebrow">BOARDING / 模拟配置</span><button data-action="close" aria-label="关闭配置">×</button></div><h2>${state.returnPage==='chat'?'配置你的对话模型':'签发你的星际船票'}</h2><p>选择同行的模型，带着问题出发。</p><div class="callout fine">演示不会连接模型。请勿输入真实 API Key；使用下方示例即可体验。</div><form id="config-form"><label for="provider">模型厂商</label><select class="field" id="provider"><option>OpenAI</option><option>Anthropic</option><option>DeepSeek</option><option>自定义兼容接口</option></select><div id="endpoint-wrap" hidden><label for="endpoint">接口地址（示例）</label><input class="field" id="endpoint" readonly value="https://example.invalid/v1"></div><label for="model">模型</label><input class="field" id="model" value="${esc(state.model)}" required placeholder="填写模型名称"><label for="demo-key">API Key（固定假值）</label><input class="field" id="demo-key" type="password" value="demo-only-not-a-real-key" readonly aria-describedby="key-help"><p class="fine" id="key-help">原型禁用真实凭据输入。正式版默认仅在本次会话使用；具体接入方式待工程方案评审。</p><label for="config-outcome">演示验证结果</label><select class="field" id="config-outcome"><option value="ok">配置有效</option><option value="invalid">Key 无效</option><option value="model">模型不可用</option><option value="quota">余额不足 / 限流</option><option value="network">网络失败</option></select><p class="config-error" id="config-error" role="alert"></p><button class="primary" id="validate" type="submit">${state.returnPage==='chat'?'验证配置并打开对话':'验证配置并生成船票'} ↗</button><p class="fine">正式版会发送问题和相关公开资料给所选服务，调用费用由访客账户承担。本原型无请求、无费用。</p></form>`);$('#provider').value=state.provider;$('#provider').addEventListener('change',()=>{$('#endpoint-wrap').hidden=$('#provider').value!=='自定义兼容接口'});$('#config-form').addEventListener('submit',e=>{e.preventDefault();const outcome=$('#config-outcome').value,provider=$('#provider').value,model=$('#model').value.trim();if(!model){$('#config-error').textContent='请填写模型名称。';return}$('#validate').disabled=true;$('#validate').textContent='正在验证（模拟）…';configTimer=setTimeout(()=>{if(!modal.open)return;if(outcome!=='ok'){const errors={invalid:'Key 无效（模拟）。请检查配置后重试。',model:'当前模型不可用（模拟）。请更换模型。',quota:'余额不足或请求限流（模拟）。可稍后重试，或直接浏览主站。',network:'连接失败（模拟）。探索进度已保留。'};$('#config-error').textContent=errors[outcome];$('#validate').disabled=false;$('#validate').textContent='重新验证';return}state.configured=true;state.provider=provider;state.model=model;if(state.returnPage==='chat'){closeDialog();chat();toast('本次模拟配置已更新。')}else ticket()},state.reduced?100:700)})}
function ticket(){openDialog(`<div class="modal-top"><span class="eyebrow">READY FOR DEPARTURE</span><button data-action="close" aria-label="关闭船票">×</button></div><div class="ticket"><span class="eyebrow">INTERPLANETARY BOARDING PASS</span><h2>MARS → EARTH</h2><p style="color:#705337">一张船票，很多种可能。</p><div class="ticket-info"><span>${esc(state.provider)}<br>${esc(state.model)}</span><span>SEAT 01<br>DEMO ONLY</span></div></div><p>配置已通过模拟验证。你的问题，准备好了吗？</p><button class="primary" data-action="ticket-scene">收好船票，去飞船 ↗</button><button class="subtle" data-action="land">直接打开对话</button>`)}
function launch(){closeDialog();stopPending();showPage('scene');state.page='flight';state.traveled=true;document.body.dataset.page='flight';$('#game').hidden=true;$('#flight').hidden=false;
 const captions={launch:'离开红色星球',cruise:'下一站，地球',entry:'穿过大气层',descent:'减速，准备着陆',hatch:'打开舱门',emerge:'脚踏实地',stretch:'长途旅行之后',gaze:'顺着目光，打开新的对话'};
 world?.startFlight({onPhase(name){$('#flight-title').textContent=captions[name]||'欢迎回来';$('#flight').dataset.shot=name},onComplete(){navigate('chat');surface.classList.add('arrival-reveal');setTimeout(()=>surface.classList.remove('arrival-reveal'),1600)}})
}
function chat(){
 if(!state.configured){showPage('chat');surface.innerHTML=`<div class="chat-gate">${backButton()}<h1>打开对话之前</h1><p>先选择模型配置。原型使用假值，不会收取真实 Key。</p><button class="primary" data-action="configure">配置模型</button><button class="subtle" data-route="home">前往主站</button></div>`;config();return}showPage('chat');
 surface.innerHTML=`<div class="chat-layout"><aside class="chat-aside"><div class="chat-brand">Fieldnotes <span>↗</span></div><button class="new-conversation" data-action="new-chat">＋ 新对话</button><span class="sidebar-label">本次访问</span><div class="session-list">${state.sessions.map((session,i)=>`<button data-session="${i}">${esc(session.title)}</button>`).join('')}<button class="current-session">${esc(state.messages.find(m=>m.role==='user')?.text||'一段新的旅程')}</button></div><div class="sidebar-bottom">${backButton()}<button data-action="recover">↙ 回收飞船 · 浏览主站</button><button data-action="replay-flight">重看归航 · 场景演绎</button><button data-action="configure">模型配置 <span>↗</span></button><button data-action="clear-key">清除本次配置</button><p>${esc(state.provider)} · ${esc(state.model)}<br>仅本次访问 · 模拟连接</p><details class="test-controls"><summary>演示异常状态</summary><select id="chat-outcome" class="field" aria-label="模拟回答结果"><option value="auto">按问题匹配示例</option><option value="empty">资料不足</option><option value="error">服务失败</option><option value="rate">限流</option></select></details></div></aside><section class="chat-main"><div class="chat-head"><button class="chat-menu" data-action="chat-menu" aria-label="打开会话与设置" aria-expanded="false">☰</button><span>Fieldnotes AI <small>模拟</small></span><button class="chip" data-action="scope">${esc(state.scope)} ⌄</button></div><div class="conversation-scroll"><div id="messages" class="messages" role="log" aria-live="polite"></div><div id="suggestions"></div></div><div class="composer-zone"><div id="chat-status" class="chat-status" role="status"></div><form class="composer" id="chat-form"><textarea id="question" aria-label="输入问题" placeholder="问问作品、文章，或关于我的信息…" maxlength="2000">${esc(state.question)}</textarea><div class="composer-bottom"><span>本站公开内容 · 回答附来源</span><button type="submit" id="send" aria-label="发送问题">↑</button></div></form><p class="chat-disclaimer">原型演示，回答为预设示例。点击引用可查看原文。</p></div></section></div>`;
 renderMessages();$('#chat-form').addEventListener('submit',e=>{e.preventDefault();ask($('#question').value)});$('#question').addEventListener('input',e=>state.question=e.target.value);$('#question').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#chat-form').requestSubmit()}})
}
function renderMessages(){
 const node=$('#messages');if(!node)return;if($('.current-session'))$('.current-session').textContent=state.messages.find(m=>m.role==='user')?.text||'一段新的旅程';
 node.innerHTML=state.messages.length?state.messages.map(m=>`<article class="message ${m.role}">${m.role==='assistant'?'<div class="answer-mark">✳ <span>Fieldnotes</span></div>':''}<div class="message-content">${esc(m.text).replace(/\n/g,'<br>')}${(m.sources||[]).map((s,i)=>` <a class="inline-citation" href="#/${s.route}" title="${esc(s.label)}" aria-label="引用 ${i+1}：${esc(s.label)}">${i+1}</a>`).join('')}</div>${m.sources?.length?`<div class="answer-sources">来源 ${m.sources.map((s,i)=>`<a href="#/${s.route}">${i+1}. ${esc(s.label)} ↗</a>`).join('')}</div>`:''}</article>`).join(''):'<div class="chat-empty"><span class="arrival-mark">✳</span><h1>降落了。<br><em>有什么想问的？</em></h1><p>关于作品、文字，以及它们背后的想法。</p></div>';
 $('#suggestions').innerHTML=state.messages.length?'':`<div class="suggestions"><button data-question="介绍一下远行手记">这个网站是怎么想的？ <span>↗</span></button><button data-question="文章里怎样看待 AI 引用？">一个回答，怎样才可信？ <span>↗</span></button><button data-question="站长有怎样的经历？">聊聊做网站的人 <span>↗</span></button></div>`;
 requestAnimationFrame(()=>{const scroll=$('.conversation-scroll');if(scroll)scroll.scrollTop=scroll.scrollHeight});
}
function stopChat(){if(state.request){clearTimeout(state.request);state.request=null;state.messages.push({role:'assistant',text:'已停止生成。没有产生完整回答。'});renderMessages();if($('#send')){$('#send').disabled=false;$('#send').textContent='↑'}if($('#chat-status'))$('#chat-status').textContent='已停止；问题已保留。'}}
function ask(question){if(state.request)return;const q=question.trim();if(!q)return;state.question=q;const result=$('#chat-outcome')?.value||'auto';if(state.scope!=='全站公开内容'&&/其他项目|全站|所有项目/.test(q)){openDialog('<h2>切换到全站问答？</h2><p>这个问题超出了当前内容范围。切换后会查找本站全部公开示例。</p><button class="primary" data-action="scope-confirm">切换并继续提问</button><button class="subtle" data-action="close">保留当前范围</button>');return}state.messages.push({role:'user',text:q});renderMessages();$('#send').disabled=true;$('#chat-status').innerHTML='正在查找公开示例… <button data-action="stop-chat">停止生成</button>';state.request=setTimeout(()=>{state.request=null;if(result==='error'||result==='rate'){if($('#chat-status'))$('#chat-status').textContent=result==='error'?'服务失败（模拟）。问题已保留，可再次发送或调整配置。':'请求限流（模拟）。问题已保留，请稍后重试。';if($('#send'))$('#send').disabled=false;return}let text,sources=[];if(result==='empty'||/经历|姓名|收入|工作|年龄|住址|公司/.test(q)){text='本站尚未提供可核对的个人资料，我不能据此编造站长的经历。你可以先查看项目设计示例，或等站长补充公开介绍。';sources=[{label:'关于 · 待补充',route:'about'}]}else if(/引用|来源|博客|文章/.test(q)){text='这份示例强调：回答应来自获准公开的材料，引用要能打开原文；资料不足时明确说明不知道。打开下面的文章可以核对这些设计约定。';sources=[{label:'一个回答，也应该有来路',route:'article/sources/section-1'}]}else if(/Agent|管理|发布/.test(q)){text='站长管理演示采用“先提案，再确认”：展示具体差异，确认对应内容版本，分别报告保存、发布和来源更新。访客问答不能执行管理写入。';sources=[{label:'给 Agent 一条清楚的边界',route:'article/boundaries/section-0'}]}else if(/远行|火星|网站|项目|探索|铲子/.test(q)){text='远行手记是这份个人站原型的设计名称。它用火星探索串起打造铲子、挖宝、配置模型与飞往地球的旅程，也允许砸炉或直接浏览。它目前是演示原型，不是已上线的真实 AI 产品。';sources=[{label:'远行手记 · 项目示例',route:'project/mars/section-1'},{label:'让探索有意义',route:'article/explore/section-0'}]}else{text='这份原型没有找到能支持该问题的示例资料。你可以问远行手记的设计、文章中的引用原则，或站长 Agent 的确认流程。';}state.messages.push({role:'assistant',text,sources});state.question='';renderMessages();if($('#question'))$('#question').value='';if($('#send'))$('#send').disabled=false;if($('#chat-status'))$('#chat-status').textContent='回答完成 · 预设内容模拟';},1200)}
function admin(){showPage('admin');surface.innerHTML=`<div class="surface-head"><div><span class="eyebrow">OWNER STUDIO / 演示</span><h1>把想法，整理成更新。</h1></div><p>模拟站长工作台，不代表已登录或具有真实发布权限。</p></div><div class="subnav">${backButton('home','chip')}<button class="chip" data-route="home">前往主站</button><button class="chip" data-action="records">执行与版本记录</button><button class="chip" data-action="admin-expire">模拟登录过期</button></div><div class="admin-grid"><section class="panel"><h2>这次想改什么？</h2><label for="admin-kind">内容目标</label><select class="field" id="admin-kind"><option value="project">更新项目介绍</option><option value="article">新建文章草稿</option></select><textarea id="admin-input" class="field" aria-label="更新要求" placeholder="例如：强调访客可以直接浏览，不必完成探索。">强调访客可以直接浏览，不必完成探索。</textarea><p class="fine">仅使用提供的材料；原型按固定规则生成示例提案。</p><button class="primary" data-action="propose">生成修改提案 ↗</button></section><section class="panel" id="proposal"><span class="eyebrow">REVIEW BEFORE PUBLISH</span><h2>先看差异，再决定。</h2><p>当前项目版本 v${state.version}</p><p>${esc(state.published)}</p><p class="fine">没有确认，就不会发生模拟发布。</p></section></div>${footer()}`;renderProposalState()}
function propose(){if(state.proposal?.status==='executing'){toast('当前操作仍在执行，请等待结果。');return}const input=$('#admin-input').value.trim(),kind=$('#admin-kind').value;if(!input){toast('请先提供修改目标或材料。');return}if(/删除|发邮件|改代码|购买/.test(input)){toast('该操作不在首版内容管理范围内。');return}state.proposal={kind,before:kind==='article'?'（尚无草稿）':state.published,after:kind==='article'?'示例草稿：'+input:'让探索成为个人网站的一部分。访客也可随时直接浏览项目与文章。\n修改依据：'+input,version:state.version,status:'pending'};proposalView()}
function proposalView(){const p=state.proposal;if(!p)return;$('#proposal').innerHTML=`<span class="eyebrow">PROPOSAL / v${p.version}</span><h2>${p.kind==='article'?'新建文章草稿':'更新「远行手记」介绍'}</h2><p class="fine">影响：示例内容、主站展示与问答来源（均模拟）</p><div class="diff before"><small>修改前</small><br>${esc(p.before)}</div><div class="diff after"><small>修改后</small><br>${esc(p.after).replace(/\n/g,'<br>')}</div><label for="publish-mode">演示执行结果</label><select class="field" id="publish-mode"><option value="ok">保存、发布、来源更新成功</option><option value="partial">发布成功，来源更新失败</option><option value="failed">保存失败</option><option value="conflict">内容版本冲突</option><option value="unknown">结果待核实</option></select><div class="actions"><button class="primary" data-action="publish">确认${p.kind==='article'?'保存草稿':'发布'} · 模拟</button><button class="subtle" data-action="cancel-proposal">取消</button></div>`}
function publish(){const p=state.proposal;if(!p||p.status!=='pending')return;const mode=$('#publish-mode').value;if(mode==='conflict'||p.version!==state.version){p.status='stale';$('#proposal').innerHTML='<h2>提案已失效</h2><p>目标内容版本变化，请重新生成差异。旧确认不能继续使用。</p>';return}p.status='executing';$('#proposal').innerHTML='<h2>正在执行（模拟）…</h2><p>此期间不会重复提交。</p>';setTimeout(()=>{if(state.proposal!==p)return;if(mode==='failed'){p.status='failed';renderProposalState();return}if(mode==='unknown'){p.status='unknown';renderProposalState();return}finishPublish(mode)},700)}
function finishPublish(mode){const p=state.proposal;if(!p||p.status==='done')return;if(p.kind==='project'){state.records.push({version:state.version,text:state.published});state.published=p.after;state.version++}p.status='done';p.result=mode;renderProposalState()}
function renderProposalState(){const p=state.proposal,node=$('#proposal');if(state.page!=='admin'||!node||!p)return;
 if(p.status==='pending'){proposalView();return}
 const views={executing:'<h2>正在执行（模拟）…</h2><p>无需重复提交。</p>',failed:'<h2>保存失败（模拟）</h2><p>没有发布任何修改。</p><button class="primary" data-action="retry-proposal">重新检查提案</button>',unknown:'<h2>结果待核实</h2><p>请核对本次操作，不要重复发布。</p><button class="primary" data-action="verify-publish">核实本次结果</button>',stale:'<h2>提案已失效</h2><p>请重新生成差异。</p>'};
 node.innerHTML=p.status==='done'?`<span class="eyebrow">EXECUTION / 模拟结果</span><h2>${p.kind==='article'?'草稿已保存':'内容已发布'}</h2><p>内容保存：成功<br>站点发布：${p.kind==='article'?'未执行（仅草稿）':'成功'}<br>问答来源：${p.kind==='article'?'未执行':p.result==='partial'?'更新失败':'更新成功'}</p>${p.result==='partial'?'<button class="primary" data-action="retry-index">重试来源更新 · 模拟</button>':''}<button class="subtle" data-action="records">查看版本记录</button>`:views[p.status]||'';
}
function records(){openDialog(`<div class="modal-top"><h2>版本记录 · 模拟</h2><button data-action="close" aria-label="关闭记录">×</button></div><p>当前项目版本 v${state.version}</p>${state.records.length?state.records.map((r,i)=>`<div class="diff before"><strong>v${r.version}</strong><p>${esc(r.text)}</p><button class="subtle" data-restore="${i}">预览恢复差异</button></div>`).join(''):'<p>暂无已发布的历史版本。先执行一次项目更新。</p>'}`)}
function restore(i){const r=state.records[i];if(!r)return;openDialog(`<h2>恢复到 v${r.version}？</h2><p>恢复会生成新版本，并覆盖当前这段项目介绍。</p><div class="diff before">当前：${esc(state.published)}</div><div class="diff after">恢复为：${esc(r.text)}</div><button class="primary" data-confirm-restore="${i}" data-version="${state.version}">确认恢复 · 模拟</button><button class="subtle" data-action="restore-back">取消恢复，返回记录</button>`)}
function renderRoute(){stopChat();stopPending();const route=location.hash.slice(2)||'scene';if(route==='scene')scene();else if(['home','projects','articles'].includes(route))home(route);else if(route==='about')about();else if(route==='contact')contact();else if(route==='social'){showPage('social');surface.innerHTML=socialView(backButton())+footer()}else if(route==='chat')chat();else if(route==='admin')admin();else if(route.startsWith('project/'))detail('project',route.split('/')[1],route.split('/')[2]);else if(route.startsWith('article/'))detail('article',route.split('/')[1],route.split('/')[2]);else{showPage('404');surface.innerHTML='<h1>这条路线还未被发现。</h1><button class="primary" data-route="home">前往主站</button>'}}
function act(action,b){if(storyAction(action))return;switch(action){case'back':navigation.back(b.dataset.fallback||'home');break;case'chat-menu':{const open=$('.chat-aside').classList.toggle('expanded');b.setAttribute('aria-expanded',String(open));break}case'home':navigate('home');break;case'scene':navigate('scene');break;case'ai':state.scope='全站公开内容';state.configured?navigate('chat'):config();break;case'configure':config();break;case'close':closeDialog();break;case'launch':launch();break;case'replay-flight':world?.reset();launch();break;case'land':closeDialog();navigate('chat');break;case'recover':surface.classList.add('recovering');storyTimer=setTimeout(()=>{surface.classList.remove('recovering');navigate('home');toast('飞船已回收，本次对话仍然保留。')},state.reduced?0:500);break;case'clear-key':state.configured=false;stopChat();navigate('home');toast('本次模拟配置已清除。');break;case'new-chat':stopChat();if(state.messages.length)state.sessions.push({title:state.messages.find(m=>m.role==='user')?.text||'对话',messages:state.messages});state.messages=[];state.question='';chat();break;case'ask-context':state.scope=b.dataset.context;state.configured?navigate('chat'):config();break;case'scope':openDialog(`<h2>问答范围</h2><p>当前：${esc(state.scope)}</p><button class="primary" data-action="scope-all">切换到全站公开内容</button><button class="subtle" data-action="close">保留当前范围</button>`);break;case'scope-all':state.scope='全站公开内容';closeDialog();chat();break;case'scope-confirm':state.scope='全站公开内容';closeDialog();chat();ask(state.question);break;case'stop-chat':stopChat();break;case'propose':propose();break;case'publish':publish();break;case'cancel-proposal':state.proposal=null;$('#proposal').innerHTML='<h2>提案已取消</h2><p>没有发生内容变更或发布。</p>';break;case'retry-proposal':state.proposal.status='pending';proposalView();break;case'verify-publish':finishPublish('ok');break;case'retry-index':if(state.proposal)state.proposal.result='ok';$('#proposal').innerHTML='<h2>来源更新成功 · 模拟</h2><p>内容保存、站点发布与问答来源均已完成。</p><button class="subtle" data-action="records">查看版本记录</button>';break;case'restore-back':records();break;case'records':records();break;case'admin-expire':state.proposal=null;openDialog('<h2>登录已过期 · 模拟</h2><p>执行已阻止。重新进入演示不会自动发布。</p><button class="primary" data-action="admin-login">重新进入演示</button><button class="subtle" data-action="close">取消</button>');$('#proposal').innerHTML='<h2>请重新进入演示</h2><p>旧提案不再可执行。</p>';break;case'admin-login':closeDialog();admin();break}}
document.addEventListener('click',e=>{const link=e.target.closest('a[href^="#/"]');if(link&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey&&e.button===0){e.preventDefault();navigate(link.getAttribute('href').slice(2));return}const b=e.target.closest('button');if(!b)return;if(b.dataset.session!==undefined){stopChat();const selected=state.sessions.splice(Number(b.dataset.session),1)[0];if(state.messages.length)state.sessions.push({title:state.messages.find(m=>m.role==='user')?.text||'对话',messages:state.messages});state.messages=selected.messages;state.question='';chat();return}if(b.dataset.route)navigate(b.dataset.route);if(b.dataset.action)act(b.dataset.action,b);if(b.dataset.move)world?.move(b.dataset.move);if(b.dataset.question){$('#question').value=b.dataset.question;ask(b.dataset.question)}if(b.dataset.section)document.getElementById(b.dataset.section)?.scrollIntoView({behavior:state.reduced?'instant':'smooth',block:'start'});if(b.dataset.restore!==undefined)restore(Number(b.dataset.restore));if(b.dataset.confirmRestore!==undefined){if(Number(b.dataset.version)!==state.version){toast('当前版本已改变，请重新检查。');return}const old=state.records[Number(b.dataset.confirmRestore)];state.records.push({version:state.version,text:state.published});state.published=old.text;state.version++;closeDialog();admin();toast('已恢复为新版本 v'+state.version+'（模拟）。')}});
// Resolve shortcuts from visible buttons so keyboard and pointer share all stage/proximity guards.
window.addEventListener('keydown',event=>{
 const blocked=state.page!=='scene'||state.busy||modal.open||Boolean(event.target.closest?.('input,textarea,select,[contenteditable]:not([contenteditable="false"])'));
 const buttons=[...document.querySelectorAll('#game .actions button[data-action]:not(:disabled)')];
 const action=shortcutAction(event,buttons.map(b=>b.dataset.action),blocked);
 if(action){event.preventDefault();buttons.find(b=>b.dataset.action===action)?.click()}
});
$('#motion').addEventListener('click',()=>{state.reduced=!state.reduced;document.body.classList.toggle('reduced',state.reduced);$('#motion').setAttribute('aria-pressed',String(state.reduced));world?.reduce(state.reduced);toast(state.reduced?'已减少动效。核心流程仍可使用。':'已恢复动效。')});document.body.classList.toggle('reduced',state.reduced);$('#motion').setAttribute('aria-pressed',String(state.reduced));navigation=createNavigation(window,readView,(_,view)=>{renderRoute();restoreView(view)});navigation.start();
// Agent-facing read-back shares the same prototype state; never exposes credentials.
const mc=document.modelContext;if(mc?.registerTool){const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});for(const tool of [{name:'read_journey_state',title:'Read prototype journey',description:'Read current visible Mars prototype progress; no credentials or real AI.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected empty object');return {page:state.page,stage:state.stage,configured:state.configured,simulated:true,world:world?.snapshot()}}},{name:'navigate_prototype',title:'Navigate prototype',description:'Navigate to a visible prototype page. Does not publish content or configure a real model.',inputSchema:{type:'object',properties:{page:{type:'string',enum:['scene','home','projects','articles','about','contact','admin']}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(!input||Object.keys(input).length!==1||!['scene','home','projects','articles','about','contact','admin'].includes(input.page))throw Error('Invalid page');navigate(input.page);await new Promise(r=>setTimeout(r,30));return{page:state.page,simulated:true}}}]){try{Promise.resolve(mc.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch{}}}
